	SetSignalMask(SIG_AIM)
	Turn(turret, y_axis, heading, rad(250))
	Turn(launcher, x_axis, -pitch, rad(150))
	WaitForTurn(turret, y_axis)
	WaitForTurn(launcher, x_axis)
	StartThread(RestoreAfterDelay)
	return true
end

function script.FireWeapon(num)
	if gun_index == 0 then
		Sleep(150)
	end
	if gun_index == 1 then
		Sleep(150)
	end
	gun_index = gun_index == 0 and 1 or 0
end

local function HitByWeapon(x, z)
